60	Disasm parse_disasm(const std::string& raw) {
61	  Disasm m;
62	  std::istringstream ss(raw);
63	  // Matches: optional leading whitespace, hex digits, colon, whitespace,
64	  // then mnemonic. Works for both GNU and LLVM objdump.
65	  static const std::regex re(R"(^\s*([0-9a-fA-F]+):\s+(\S+)(?:\s+(.*))?$)");
66	  std::string line;
67	  while (std::getline(ss, line)) {
68	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
69	      line.pop_back();
70	    std::smatch sm;
71	    if (!std::regex_match(line, sm, re)) continue;
72	    uint64_t pc;
73	    try {
74	      pc = std::stoull(sm[1], nullptr, 16);
75	    } catch (...) {
76	      continue;
77	    }
78	    std::string mn = sm[2];
79	    std::string ops = sm.size() > 3 ? sm[3].str() : "";
80	    while (!ops.empty() && (ops.back() == ' ' || ops.back() == '\t'))
81	      ops.pop_back();
82	    m[pc] = {std::move(mn), std::move(ops)};
83	  }
84	  return m;
85	}
