190	uint64_t measure_ret_pc(const Disasm& disasm, uint64_t fn_entry,
191	                        uint64_t fn_end) {
192	  uint64_t ret_pc = fn_end - 4;  // safe default (standard ret is 4 bytes)
193	  auto it = disasm.lower_bound(fn_end);
194	  if (it != disasm.begin()) {
195	    --it;
196	    if (it->first >= fn_entry) ret_pc = it->first;
197	  }
198	  return ret_pc;
199	}
