201	std::string src_basename(const std::string& s) {
202	  if (s.empty()) return "";
203	  // "path:line[ (extra)]" -> "basename(path):line[ ...]"
204	  auto sp = s.find(' ');
205	  std::string head = (sp != std::string::npos) ? s.substr(0, sp) : s;
206	  std::string tail = (sp != std::string::npos) ? s.substr(sp) : "";
207	  auto slash = head.rfind('/');
208	  return ((slash != std::string::npos) ? head.substr(slash + 1) : head) + tail;
209	}
