219	std::string render_llm(const std::vector<Loop>& loops,
220	                       const std::vector<LoopSyms>& syms, uint64_t total_iters,
221	                       const std::string& target_name, const Disasm& disasm,
222	                       int min_iters, bool rvv_filter) {
223	  std::string out;
224	  if (loops.empty()) return out;
225	
226	  auto pct = [&](uint64_t n) -> double {
227	    return total_iters ? 100.0 * static_cast<double>(n) /
228	                             static_cast<double>(total_iters)
229	                       : 0.0;
230	  };
231	
232	  // Header + TL;DR
233	  {
234	    const Loop& top = loops[0];
235	    const LoopSyms& ts = syms[0];
236	    auto rvv = rvv_in_range(disasm, top.start, top.end);
237	    std::string rvv_str;
238	    if (!rvv.empty()) {
239	      std::vector<std::string> uniq;
240	      for (const auto& r : rvv)
241	        if (std::find(uniq.begin(), uniq.end(), r.mn) == uniq.end())
242	          uniq.push_back(r.mn);
243	      rvv_str = "RVV (";
244	      for (size_t i = 0; i < std::min(uniq.size(), size_t{3}); ++i) {
245	        if (i) rvv_str += ", ";
246	        rvv_str += uniq[i];
247	      }
248	      if (uniq.size() > 3)
249	        rvv_str += ", +" + std::to_string(uniq.size() - 3) + " more";
250	      rvv_str += ")";
251	    } else {
252	      rvv_str = "scalar";
253	    }
254	    std::string src_s = src_basename(ts.src_start);
255	    if (src_s.empty()) src_s = "?";
256	    std::string nest_str = top.parent >= 0
257	                               ? "nested inside " +
258	                                     loops[static_cast<size_t>(top.parent)].id
259	                               : "top-level (no parent loop)";
260	    std::string child_str;
261	    if (!top.children.empty()) {
262	      child_str = "and contains " + std::to_string(top.children.size()) +
263	                  " inner loop(s): ";
264	      for (size_t i = 0; i < top.children.size(); ++i) {
265	        if (i) child_str += ", ";
266	        child_str += loops[static_cast<size_t>(top.children[i])].id;
267	      }
268	    } else {
269	      child_str = "and contains no inner loop";
270	    }
271	    appendf(out, "# HotIterationLoop Report\n");
272	    appendf(out, "target:           %s\n", target_name.c_str());
273	    appendf(out, "total_iters:      %llu\n", (unsigned long long)total_iters);
274	    appendf(out, "reported_loops:   %zu\n", loops.size());
275	    appendf(out, "min_iters:        %d\n", min_iters);
276	    appendf(out, "rvv_filter:       %s\n", rvv_filter ? "on" : "off");
277	    appendf(out, "\n## TL;DR\n");
278	    appendf(out,
279	            "Hottest loop is %s in `%s` (%s), %llu iters = %.1f%% of total. "
280	            "Body is %s. It is %s, %s.\n",
281	            top.id.c_str(), ts.fn_name.c_str(), src_s.c_str(),
282	            (unsigned long long)top.iters, pct(top.iters), rvv_str.c_str(),
283	            nest_str.c_str(), child_str.c_str());
284	    appendf(out, "\n## Loops\n");
285	  }
286	
287	  for (size_t idx = 0; idx < loops.size(); ++idx) {
288	    const Loop& loop = loops[idx];
289	    const LoopSyms& ls = syms[idx];
290	    appendf(out, "\n### %s%s  (%.1f%% of total)\n", loop.id.c_str(),
291	            idx == 0 ? " [hottest]" : "", pct(loop.iters));
292	    appendf(out, "iters:        %llu\n", (unsigned long long)loop.iters);
293	    appendf(out, "function:     %s -> %s\n", ls.sym_start.c_str(),
294	            ls.sym_end.c_str());
295	
296	    // measure: whole enclosing function (entry -> ret).
297	    if (ls.fn_entry != 0 && ls.fn_end != 0) {
298	      uint64_t ret_pc = measure_ret_pc(disasm, ls.fn_entry, ls.fn_end);
299	      appendf(out,
300	              "measure:      --pc-start 0x%llx --pc-end 0x%llx"
301	              "  (all of %s: entry -> ret)\n",
302	              (unsigned long long)ls.fn_entry, (unsigned long long)ret_pc,
303	              ls.fn_name.c_str());
304	    }
305	
306	    const std::string& sf = ls.src_start;
307	    const std::string& se = ls.src_end;
308	    if (!sf.empty() && !se.empty() && sf == se)
309	      appendf(out, "source:       %s\n", src_basename(sf).c_str());
310	    else
311	      appendf(out, "source:       %s -> %s\n",
312	              (sf.empty() ? "?" : src_basename(sf)).c_str(),
313	              (se.empty() ? "?" : src_basename(se)).c_str());
314	
315	    if (!ls.code_snippet.empty()) {
316	      std::string snippet = ls.code_snippet;
317	      if (snippet.size() > 200) snippet = snippet.substr(0, 197) + "...";
318	      appendf(out, "code:         %s\n", snippet.c_str());
319	    }
320	
321	    auto rvv = rvv_in_range(disasm, loop.start, loop.end);
322	    if (!rvv.empty()) {
323	      appendf(out, "rvv:          yes (%zu insn%s)\n", rvv.size(),
324	              rvv.size() == 1 ? "" : "s");
325	      appendf(out, "rvv_insns:\n");
326	      for (size_t i = 0; i < std::min(rvv.size(), size_t{8}); ++i)
327	        appendf(out, "  - 0x%llx  %-10s %s\n", (unsigned long long)rvv[i].pc,
328	                rvv[i].mn.c_str(), rvv[i].ops.c_str());
329	      if (rvv.size() > 8)
330	        appendf(out, "  - ... (%zu more)\n", rvv.size() - 8);
331	    } else {
332	      appendf(out, "rvv:          no\n");
333	    }
334	
335	    appendf(out, "parent:       %s\n",
336	            loop.parent >= 0 ? loops[static_cast<size_t>(loop.parent)].id.c_str()
337	                             : "-");
338	    if (!loop.children.empty()) {
339	      appendf(out, "children:     [");
340	      for (size_t i = 0; i < loop.children.size(); ++i) {
341	        if (i) appendf(out, ", ");
342	        appendf(out, "%s",
343	                loops[static_cast<size_t>(loop.children[i])].id.c_str());
344	      }
345	      appendf(out, "]\n");
346	    } else {
347	      appendf(out, "children:     []\n");
348	    }
349	
350	    auto callees = calls_in_range(disasm, loop.start, loop.end);
351	    if (!callees.empty()) {
352	      appendf(out, "calls:\n");
353	      for (size_t i = 0; i < std::min(callees.size(), size_t{8}); ++i)
354	        appendf(out, "  - 0x%llx  %s -> %s\n",
355	                (unsigned long long)callees[i].pc, callees[i].mn.c_str(),
356	                callees[i].target.c_str());
357	      if (callees.size() > 8)
358	        appendf(out, "  - ... (%zu more)\n", callees.size() - 8);
359	    } else {
360	      appendf(out, "calls:        []\n");
361	    }
362	  }
363	  return out;
364	}
