366	std::string render_table(const std::vector<LoopEdge>& rows,
367	                         const std::vector<LoopSyms>& syms, int min_iters,
368	                         bool rvv_filter) {
369	  std::string out;
370	  bool have_src = false;
371	  for (const auto& s : syms)
372	    if (!s.src_start.empty() || !s.src_end.empty()) have_src = true;
373	
374	  auto srcpair = [&](const LoopSyms& s) -> std::string {
375	    std::string a = src_basename(s.src_start), b = src_basename(s.src_end);
376	    if (!a.empty() && a == b) return a;
377	    return (a.empty() ? "?" : a) + " -> " + (b.empty() ? "?" : b);
378	  };
379	
380	  appendf(out, "# hot loops (iters >= %d", min_iters);
381	  if (rvv_filter) appendf(out, ", RVV-only");
382	  appendf(out, "), sorted desc, top %zu\n", rows.size());
383	
384	  size_t w_iter = 5;  // strlen("iters")
385	  for (const auto& r : rows) {
386	    char buf[24];
387	    snprintf(buf, sizeof(buf), "%llu", (unsigned long long)r.iters);
388	    w_iter = std::max(w_iter, strlen(buf));
389	  }
390	  const size_t w_pc = 18;
391	  size_t w_sym = 8;  // strlen("location")
392	  for (const auto& s : syms)
393	    w_sym = std::max(w_sym, s.sym_start.size() + 4 + s.sym_end.size());
394	
395	  if (have_src) {
396	    appendf(out, "%*s | %-*s -> %-*s | %-*s | source\n",
397	            static_cast<int>(w_iter), "iters", static_cast<int>(w_pc),
398	            "start_pc", static_cast<int>(w_pc), "end_pc",
399	            static_cast<int>(w_sym), "location");
400	  } else {
401	    appendf(out, "%*s | %-*s -> %-*s | location\n", static_cast<int>(w_iter),
402	            "iters", static_cast<int>(w_pc), "start_pc",
403	            static_cast<int>(w_pc), "end_pc");
404	  }
405	  size_t sep = w_iter + 3 + w_pc + 4 + w_pc + 3 + w_sym;
406	  if (have_src) sep += 3 + 12;
407	  appendf(out, "%s\n", std::string(sep, '-').c_str());
408	
409	  for (size_t i = 0; i < rows.size(); ++i) {
410	    const LoopEdge& r = rows[i];
411	    std::string loc = syms[i].sym_start + " -> " + syms[i].sym_end;
412	    if (have_src)
413	      appendf(out, "%*llu | 0x%016llx -> 0x%016llx | %-*s | %s\n",
414	              static_cast<int>(w_iter), (unsigned long long)r.iters,
415	              (unsigned long long)r.start, (unsigned long long)r.end,
416	              static_cast<int>(w_sym), loc.c_str(), srcpair(syms[i]).c_str());
417	    else
418	      appendf(out, "%*llu | 0x%016llx -> 0x%016llx | %s\n",
419	              static_cast<int>(w_iter), (unsigned long long)r.iters,
420	              (unsigned long long)r.start, (unsigned long long)r.end,
421	              loc.c_str());
422	  }
423	  return out;
424	}
