426	std::vector<std::string> profile_qemu_argv(const ProfileQemuArgs& a) {
427	  std::vector<std::string> argv = {
428	      a.qemu_bin,
429	      "-plugin",
430	      a.plugin_so + ",limit=" + std::to_string(a.limit) +
431	          ",min_iters=" + std::to_string(a.min_iters),
432	      "-d", "plugin", "-D", a.log_path,
433	      "-M", "andes_ae350",
434	      "-cpu", a.cpu,
435	      "-nographic", "-semihosting",
436	      "-bios", a.elf,
437	  };
438	  if (!a.mem_size.empty()) {
439	    argv.push_back("-m");
440	    argv.push_back(a.mem_size);
441	  }
442	  if (!a.readconfig.empty()) {
443	    argv.push_back("-readconfig");
444	    argv.push_back(a.readconfig);
445	  }
446	  argv.insert(argv.end(), a.passthrough.begin(), a.passthrough.end());
447	  return argv;
448	}
