1	// Profile core -- the pure logic behind `andesim profile` (hot inner-loop
2	// detection via the hotIterationLoop TCG plugin).
3	//
4	// Everything here is data-in/data-out: plugin-log text -> loop edges,
5	// objdump text -> a disassembly map, filters/nesting on plain structs, and
6	// renderers that RETURN the report as a string. All process IO (QEMU spawn,
7	// objdump/addr2line, ELF symbolization) stays in cmd_profile.cpp, which
8	// precomputes per-loop symbol/source strings into LoopSyms so the renderers
9	// need no filesystem access -- that is what makes them unit-testable.
10	#ifndef ANDESIM_PROFILE_HPP
11	#define ANDESIM_PROFILE_HPP
12	
13	#include <cstdint>
14	#include <map>
15	#include <string>
16	#include <utility>
17	#include <vector>
18	
19	namespace andes_sim {
20	
21	// One backward edge observed by the plugin: header pc, tail pc, iterations.
22	struct LoopEdge {
23	  uint64_t start = 0;
24	  uint64_t end = 0;
25	  uint64_t iters = 0;
26	};
27	
28	// One disassembled instruction (objdump -d --no-show-raw-insn).
29	struct InsnInfo {
30	  std::string mnemonic;
31	  std::string operands;
32	};
33	using Disasm = std::map<uint64_t, InsnInfo>;
34	
35	struct RvvInsn {
36	  uint64_t pc;
37	  std::string mn, ops;
38	};
39	struct CallInsn {
40	  uint64_t pc;
41	  std::string mn, target;
42	};
43	
44	// A loop after nesting: parent/children reference loops in the SAME vector by
45	// index (-1 = top-level), so the vector stays copyable.
46	struct Loop {
47	  std::string id;  // "L1".."Ln", hottest first
48	  uint64_t start = 0, end = 0, iters = 0;
49	  int parent = -1;
50	  std::vector<int> children;
51	};
52	
53	// Per-loop symbol/source strings, precomputed by the caller (ELF + addr2line
54	// IO) so the renderers stay pure. Empty string = unknown.
55	struct LoopSyms {
56	  std::string sym_start;     // "name+0xoff" or raw "0x<pc>" at loop.start
57	  std::string sym_end;       // same at loop.end
