86	// Write lines to argv's stdin; capture its stdout. Used for addr2line, which
87	// takes one hex address per input line.
88	std::string capture_with_stdin(const std::vector<std::string>& argv,
89	                               const std::string& input) {
90	  if (argv.empty()) return "";
91	  int in_fds[2], out_fds[2];
92	  if (pipe(in_fds) != 0) return "";
93	  if (pipe(out_fds) != 0) {
94	    close(in_fds[0]);
95	    close(in_fds[1]);
96	    return "";
97	  }
98	  pid_t pid = fork();
99	  if (pid < 0) {
100	    close(in_fds[0]); close(in_fds[1]);
101	    close(out_fds[0]); close(out_fds[1]);
102	    return "";
103	  }
104	  if (pid == 0) {
105	    close(in_fds[1]);
106	    close(out_fds[0]);
107	    dup2(in_fds[0], STDIN_FILENO);
108	    dup2(out_fds[1], STDOUT_FILENO);
109	    if (FILE* devnull = std::fopen("/dev/null", "w"))
110	      dup2(fileno(devnull), STDERR_FILENO);
111	    close(in_fds[0]);
112	    close(out_fds[1]);
113	    std::vector<char*> cargv;
114	    cargv.reserve(argv.size() + 1);
115	    for (const auto& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
116	    cargv.push_back(nullptr);
117	    execvp(cargv[0], cargv.data());
118	    _exit(127);
119	  }
120	  close(in_fds[0]);
121	  close(out_fds[1]);
122	  const char* p = input.data();
123	  size_t rem = input.size();
124	  while (rem > 0) {
125	    ssize_t w = write(in_fds[1], p, rem);
126	    if (w < 0) break;
127	    p += w;
128	    rem -= static_cast<size_t>(w);
129	  }
130	  close(in_fds[1]);
131	  std::string out;
132	  char buf[4096];
133	  ssize_t n;
134	  while ((n = read(out_fds[0], buf, sizeof(buf))) > 0)
135	    out.append(buf, static_cast<size_t>(n));
136	  close(out_fds[0]);
137	  int status = 0;
138	  waitpid(pid, &status, 0);
139	  return out;
140	}
