142	// addr2line every pc in `pcs` against `elf_path`; unknown ("??") lines drop
143	// out, so absent keys mean "no source info".
144	std::map<uint64_t, std::string> resolve_sources(
145	    const std::string& addr2line_bin, const std::string& elf_path,
146	    const std::vector<uint64_t>& pcs) {
147	  std::map<uint64_t, std::string> result;
148	  if (addr2line_bin.empty() || pcs.empty()) return result;
149	  std::string input;
150	  for (uint64_t pc : pcs) {
151	    char buf[20];
152	    std::snprintf(buf, sizeof(buf), "0x%llx\n", (unsigned long long)pc);
153	    input += buf;
154	  }
155	  const std::string out =
156	      capture_with_stdin({addr2line_bin, "-e", elf_path}, input);
157	  std::istringstream ss(out);
158	  std::string line;
159	  size_t idx = 0;
160	  while (std::getline(ss, line) && idx < pcs.size()) {
161	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
162	      line.pop_back();
163	    if (!line.empty() && line.find("??") == std::string::npos)
164	      result[pcs[idx]] = line;
165	    ++idx;
166	  }
167	  return result;
168	}
