170	// The trimmed text of `path`'s line `lineno` ("" when unreadable).
171	std::string read_source_line(const std::string& path, int lineno) {
172	  if (path.empty() || lineno <= 0 || !fs::is_regular_file(path)) return "";
173	  std::ifstream f(path);
174	  std::string line;
175	  for (int i = 1; std::getline(f, line); ++i) {
176	    if (i != lineno) continue;
177	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n' ||
178	                             line.back() == ' ' || line.back() == '\t'))
179	      line.pop_back();
180	    auto s = line.find_first_not_of(" \t");
181	    return (s != std::string::npos) ? line.substr(s) : line;
182	  }
183	  return "";
184	}
