186	// "name+0xoff" (or "") when the ELF resolves `pc`, else the raw hex pc.
187	std::string sym_or_hex(const std::string& sym, uint64_t pc) {
188	  if (!sym.empty()) return sym;
189	  char buf[20];
190	  std::snprintf(buf, sizeof(buf), "0x%llx", (unsigned long long)pc);
191	  return buf;
192	}
