216	struct Workdir {
217	  std::string path;
218	  std::string error;
219	  Workdir() {
220	    char tmpl[] = "/tmp/andesim-profile.XXXXXX";
221	    if (::mkdtemp(tmpl))
222	      path = tmpl;
223	    else
224	      error = "cannot create the profile workdir under /tmp";
