235	int cmd_profile(const Cli& cli) {
236	  auto fail = [](const std::string& msg) {
237	    std::fprintf(stderr, "andesim profile: %s\n", msg.c_str());
238	    return 2;
239	  };
240	
241	  // profile is not `run`: reject run-only flags loudly instead of silently
242	  // ignoring them (a silently dropped --trigger would look like a hung ROI).
243	  {
244	    const struct {
245	      bool set;
246	      const char* flag;
247	    } runonly[] = {
248	        {!cli.model.empty(), "--mode"},
249	        {!cli.trigger.empty(), "--trigger"},
250	        {!cli.pc_start.empty(), "--pc-start"},
251	        {!cli.pc_end.empty(), "--pc-end"},
252	        {cli.verify, "--verify"},
253	        {!cli.kanata.empty(), "--kanata"},
254	        {cli.gdb, "--gdb"},
255	        {!cli.gdb_port.empty(), "--gdb-port"},
256	        {cli.print_memmap, "--print-memmap"},
257	    };
258	    for (const auto& r : runonly)
259	      if (r.set)
260	        return fail(std::string(r.flag) +
261	                    " is not a profile option (profile runs the whole "
262	                    "program under QEMU; see 'andesim profile --help')");
263	  }
264	
265	  if (cli.positional.empty())
266	    return fail("missing ELF (the workload to profile)");
267	  if (cli.positional.size() > 1)
268	    return fail("unexpected argument '" + cli.positional[1] +
269	                "' (extra QEMU args go after --)");
270	
271	  int limit = 0, min_iters = 0;
272	  if (!parse_positive_int(cli.limit, 50, limit))
273	    return fail("--limit must be a positive integer, got '" + cli.limit + "'");
274	  if (!parse_positive_int(cli.min_iters, 1, min_iters))
275	    return fail("--min-iters must be a positive integer, got '" +
276	                cli.min_iters + "'");
277	
278	  // Absolute, existing ELF (QEMU's -bios resolves relative paths against its
279	  // data dir, not the CWD) -- the same up-front check run's abs_elf does.
280	  std::error_code ec;
281	  const fs::path abs = fs::absolute(cli.positional[0], ec);
282	  if (ec || !fs::is_regular_file(abs))
283	    return fail("ELF not found: " + cli.positional[0]);
284	  const std::string elf = abs.string();
285	
286	  // The engine pick: exactly hybrid's -- --engine or the sole cycle-accurate
287	  // engine, with the same errors (naming the discovered candidates).
288	  Discovery disc = discover_engines();
289	  std::string err;
290	  const EngineDescriptor* acc =
291	      resolve_accurate_engine(disc.engines, cli.engine, err);
292	  if (!acc) {
293	    std::fprintf(stderr, "andesim profile: %s\n", err.c_str());
294	    for (const std::string& w : disc.warnings)
295	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
296	    return 2;
297	  }
298	  if (std::string e = elf_engine_arch_error(elf, *acc); !e.empty())
299	    return fail(e);
300	
301	  // QEMU follows the engine's width (the arch guard above already pinned the
302	  // ELF to it; an unreadable ELF falls back to the ELF's own class, then 64).
303	  const int elf_w = elf_xlen(elf);
304	  const int xlen = acc->xlen ? static_cast<int>(acc->xlen)
305	                             : (elf_w ? elf_w : 64);
306	  const EngineDescriptor qemu = builtin_qemu_arch(xlen);
307	  const std::string plugin = profile_plugin_path().string();
308	
309	  Workdir wd;
310	  if (wd.path.empty()) return fail(wd.error);
311	
312	  // engine -> QEMU cfg, the same probe + staging the hybrid fast leg uses.
313	  // "" cfg = tolerant fallback (family-default -cpu), but SAY so: matching
314	  // the engine's ISA is the whole point of profiling through an engine.
315	  const RunResult probe =
316	      run_process({acc->bin_path, "--print-qemu-config"}, 5000);
317	  const std::string cfg = stage_qemu_cfg(wd.path, probe);
318	  std::string cpu_model = cfg.empty() ? std::string() : qemu_cpu_from_cfg(probe.out);
319	  if (cpu_model.empty()) cpu_model = kDefaultQemuCpu;
320	  if (cfg.empty())
321	    log_line(kLogWarn,
322	             "[andesim] profile: engine %s gave no --print-qemu-config; "
323	             "falling back to -cpu %s (the profiled ISA may not match the "
324	             "engine)",
325	             acc->id.c_str(), cpu_model.c_str());
326	
327	  ProfileQemuArgs qa;
328	  qa.qemu_bin = qemu.bin_path;
329	  qa.plugin_so = plugin;
330	  qa.log_path = wd.path + "/plugin.log";
331	  qa.limit = limit;
332	  qa.min_iters = min_iters;
333	  qa.cpu = cpu_model + ",vlen=" + std::to_string(synced_vlen(acc->vlen));
334	  qa.mem_size = cli.mem_size;  // forwarded as plain -m; QEMU validates it
335	  qa.readconfig = cfg;
336	  qa.elf = elf;
337	  qa.passthrough = cli.passthrough;
338	  const std::vector<std::string> argv = profile_qemu_argv(qa);
339	
340	  if (cli.dry_run)
341	    return print_dry_run({argv}, {"profile [" + acc->id + "]"});
342	
343	  log_line(kLogDebug, "[andesim] profile engine=%s cpu=%s fixture=%s",
344	           acc->id.c_str(), qa.cpu.c_str(), abs.stem().string().c_str());
345	
346	  // Spawn-time checks, AFTER --dry-run so the preview needs no built QEMU.
347	  if (!fs::is_regular_file(qemu.bin_path) ||
348	      ::access(qemu.bin_path.c_str(), X_OK) != 0)
349	    return fail("qemu not found/executable: " + qemu.bin_path +
350	                " (set QEMU_BIN_DIR in config.env, or source ./setup.sh)");
351	  if (!fs::is_regular_file(plugin))
352	    return fail("plugin not built: " + plugin + " (make -C qemu_plugin)");
353	
354	  log_line(kLogTrace, "[andesim] exec profile [%s]: %s", acc->id.c_str(),
355	           render_argv(argv).c_str());
356	  const int rc = exec_passthrough(argv);
357	  if (rc == -1) return fail("failed to spawn " + qemu.bin_path);
358	  if (rc != 0)
359	    log_line(kLogWarn,
360	             "[andesim] profile: qemu exited rc=%d; the report covers what "
361	             "ran",
362	             rc);
363	
364	  std::string log_text;
365	  {
366	    std::ifstream f(qa.log_path);
367	    std::stringstream ss;
368	    ss << f.rdbuf();
369	    log_text = ss.str();
370	  }
371	
372	  if (cli.raw) {
373	    std::fputs(log_text.c_str(), stdout);
374	    return 0;
375	  }
376	
377	  auto all_rows = parse_plugin_log(log_text);
378	  if (all_rows.empty()) {
379	    std::fprintf(stderr, "andesim profile: no backward edges observed\n");
380	    return 0;
381	  }
382	  uint64_t total_iters = 0;
383	  for (const auto& r : all_rows) total_iters += r.iters;
384	
385	  // Disassembly (the RVV filter + the report's rvv/calls sections need it).
386	  const std::string objdump = resolve_objdump(cli.objdump);
387	  Disasm disasm;
388	  if (!objdump.empty() && (cli.optimize_rvv || cli.llm))
389	    disasm = parse_disasm(
390	        run_process({objdump, "-d", "--no-show-raw-insn", elf}, 60000).out);
391	  if (objdump.empty() && cli.optimize_rvv)
392	    log_line(kLogWarn,
393	             "[andesim] profile: no objdump found; the RVV filter drops "
394	             "every loop -- install a riscv objdump or pass "
395	             "--no-optimize-rvv");
396	
397	  auto rows = filter_loops(all_rows, min_iters, cli.optimize_rvv, disasm,
398	                           limit);
399	  if (rows.empty()) {
400	    std::fprintf(stderr, "andesim profile: no loops with iters >= %d%s\n",
401	                 min_iters,
402	                 cli.optimize_rvv ? " containing RVV instructions" : "");
403	    return 0;
404	  }
405	
406	  // Source resolution (addr2line), unless --no-source.
407	  std::map<uint64_t, std::string> src_map;
408	  if (!cli.no_source) {
409	    const std::string a2l = !cli.addr2line.empty()
410	                                ? cli.addr2line
411	                                : find_first({"llvm-addr2line", "addr2line",
412	                                              "riscv64-unknown-elf-addr2line",
413	                                              "riscv32-unknown-elf-addr2line",
414	                                              "riscv64-linux-gnu-addr2line"});
415	    std::vector<uint64_t> pcs;
416	    for (const auto& r : rows) {
417	      pcs.push_back(r.start);
418	      pcs.push_back(r.end);
419	    }
420	    std::sort(pcs.begin(), pcs.end());
421	    pcs.erase(std::unique(pcs.begin(), pcs.end()), pcs.end());
422	    src_map = resolve_sources(a2l, elf, pcs);
423	  }
424	
425	  // One syms vector serves both renderers: build_loops keeps row order, so
426	  // `loops` is parallel to `rows`.
427	  std::vector<LoopSyms> syms;
428	  syms.reserve(rows.size());
429	  for (const auto& r : rows)
430	    syms.push_back(make_syms(elf, r.start, r.end, src_map));
431	
432	  const std::string report =
433	      cli.llm ? render_llm(build_loops(rows, limit), syms, total_iters,
434	                           abs.filename().string(), disasm, min_iters,
435	                           cli.optimize_rvv)
436	              : render_table(rows, syms, min_iters, cli.optimize_rvv);
437	  std::fputs(report.c_str(), stdout);
438	  return 0;
439	}
