50	// Resolve `path` to an absolute, EXISTING ELF. Returns the resolved string on
51	// success; on failure prints an error tagged with `ctx` and returns "". The
52	// existence check is here, at the one resolver fast/cycle/cycle-gdb share, so a
53	// missing path fails with a clear "ELF not found" instead of being handed to the
54	// engine (e.g. qemu's cryptic "Unable to find the RISC-V BIOS"). Mirrors the
55	// up-front check run_hybrid already does.
56	std::string abs_elf(const std::string& path, const std::string& ctx) {
57	  std::error_code ec;
58	  fs::path abs = fs::absolute(path, ec);
59	  if (ec) {
60	    std::fprintf(stderr, "andesim run %s: cannot resolve ELF '%s'\n",
61	                 ctx.c_str(), path.c_str());
62	    return "";
63	  }
64	  if (!fs::is_regular_file(abs, ec)) {
65	    std::fprintf(stderr, "andesim run %s: ELF not found: %s\n", ctx.c_str(),
66	                 path.c_str());
67	    return "";
68	  }
69	  return abs.string();
70	}
71	
72	// Validate the lone-ELF positional shape the standalone models require: print
73	// the diagnostic and return 2 on a violation, else 0. Split out so `cycle`
74	// can reject a missing/extra ELF BEFORE paying for engine discovery (which
75	// spawns a --describe subprocess per Verilator build). `model` labels the error.
76	int check_one_elf(const Cli& cli, const char* model) {
77	  if (cli.positional.empty()) {
78	    std::fprintf(stderr,
79	                 "andesim run --mode %s: missing ELF (the workload to run; "
80	                 "e.g. a tests/fixtures/<name>.elf)\n",
81	                 model);
82	    return 2;
83	  }
84	  if (cli.positional.size() > 1) {
85	    std::fprintf(stderr,
86	                 "andesim run --mode %s: unexpected argument '%s' "
87	                 "(engine args go after --)\n",
88	                 model, cli.positional[1].c_str());
89	    return 2;
90	  }
91	  return 0;
92	}
93	
94	// elf_engine_arch_error (the ELF-vs-engine width guard shared with profile)
95	// lives in engine_registry.hpp, next to resolve_accurate_engine.
96	
97	// print_dry_run (the shared --dry-run preview) lives in argv.hpp, next to
98	// render_argv.
99	
100	// `run --mode cycle` presentation: spawn the engine, hiding its startup banner
101	// and verbose [info] log (VsimFilter), relaying only the program's own output
102	// and any real diagnostics, then restate the lifted cycle count as andesim's own
103	// one-line result under the [andesim] prefix. The count is printed AFTER the run
104	// (the engine logs it at exit), so it follows the program output. Returns the
105	// engine exit code. Unlike fast's exec_passthrough, the parent stays alive to
106	// filter -- fine, because cycle (without --gdb) is a batch run, not interactive.
107	int run_cycle_clean(const std::vector<std::string>& argv) {
108	  VsimFilter filter;
109	  const int rc = run_line_filtered(
110	      argv, [&filter](int stream, std::string_view line) {
111	        std::FILE* dst = nullptr;
112	        switch (filter.classify(stream, line)) {
113	          case VsimFilter::Dest::kStdout: dst = stdout; break;
114	          case VsimFilter::Dest::kStderr: dst = stderr; break;
115	          case VsimFilter::Dest::kDrop: return;
116	        }
117	        std::fwrite(line.data(), 1, line.size(), dst);
118	        std::fputc('\n', dst);
119	      });
120	  if (const std::optional<uint64_t> c = filter.cycles())
121	    log_result(kLogInfo, "[andesim] %llu cycles",
122	               static_cast<unsigned long long>(*c));
123	  return rc;
124	}
125	
126	// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
127	// then run the resolved engine standalone with `extra` (model flags the
128	// framework forwards, e.g. fast's -m) followed by the post-`--` args verbatim.
129	// `clean_output` picks how the engine's output is presented: fast inherits the
130	// stdio transparently (exec_passthrough -- an interactive gdbstub / monitor /
131	// semihosting console works unchanged); cycle filters out the engine's banner +
132	// [info] noise and restates the cycle count (run_cycle_clean). Either way the
133	// exit code propagates. The per-model engine + selection are resolved by the
134	// caller; `model` here only labels the positional diagnostics.
135	// `boot_elf_override`: --runtime linux (U2) boots a staged vlinux.elf instead
136	// of the positional ELF (which stays the APP path -- still validated to
137	// exist, still what the manifest embeds); empty means "boot the ELF as given"
138	// (every other caller).
139	int run_standalone(const Cli& cli, const EngineDescriptor& eng,
140	                   const char* model, const std::vector<std::string>& extra = {},
141	                   bool clean_output = false,
142	                   const std::string& boot_elf_override = {}) {
143	  if (int rc = check_one_elf(cli, model)) return rc;
144	  // QEMU's -bios flag searches its data directory for relative paths rather
145	  // than the CWD; resolve to absolute so both QEMU and vsim find the ELF.
146	  const std::string elf = abs_elf(cli.positional[0], "--mode " + std::string(model));
147	  if (elf.empty()) return 2;
148	  const std::string& boot_elf =
149	      boot_elf_override.empty() ? elf : boot_elf_override;
150	  std::vector<std::string> args = extra;
151	  args.insert(args.end(), cli.passthrough.begin(), cli.passthrough.end());
152	  std::string err;
153	  const std::vector<std::string> argv =
154	      passthrough_argv(eng, "standalone", boot_elf, args, err);
155	  if (!err.empty()) {
156	    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
157	    return 2;
158	  }
159	  // --dry-run: print the exact engine command and stop, spawning nothing -- the
160	  // full qemu/vsim command (incl. -bios <elf> and any post-`--`).
161	  if (cli.dry_run)
162	    return print_dry_run({argv}, {std::string("standalone [") + eng.id + "]"});
163	  // Trace mirrors the hybrid legs' exec lines: emitted BEFORE the spawn, so a
164	  // wedged engine still leaves the exact command in the log.
165	  log_line(kLogTrace, "[andesim] exec standalone [%s]: %s", eng.id.c_str(),
166	           render_argv(argv).c_str());
167	  return clean_output ? run_cycle_clean(argv) : exec_passthrough(argv);
168	}
169	
170	// `run --mode fast`: QEMU alone, functional, transparent passthrough. Needs
171	// only the built-in qemu descriptor, so it resolves that directly rather than
172	// discover_engines(), which would spawn a --describe subprocess per Verilator
173	// build only to discard them all here.
174	int run_fast(const Cli& cli) {
175	  // fast is QEMU-only; an explicit engine must name 'qemu64' (rv64) or 'qemu32'.
176	  if (!cli.engine.empty() && cli.engine != kQemuId64 && cli.engine != kQemuId32) {
177	    std::fprintf(stderr,
178	                 "andesim run --mode fast: engine must be 'qemu64' or 'qemu32', "
179	                 "got '%s'\n",
180	                 cli.engine.c_str());
181	    return 2;
182	  }
183	  // --runtime linux (U2, ROADMAP_LINUX_RUNTIME.md) defaults --mem-size to 1G
184	  // (the app + vlinux's own arenas) when the user did not pick one.
185	  std::string mem_size_spec = cli.mem_size;
186	  if (cli.runtime == "linux" && mem_size_spec.empty()) mem_size_spec = "1G";
187	
188	  // --mem-size forwards a plain `-m`; QEMU validates it (as-is, no mmap, no
189	  // default injected). It precedes the post-`--` args, so a user's own -m wins.
190	  std::string err;
191	  std::vector<std::string> extra = qemu_m_args(mem_size_spec, err);
192	  if (!err.empty()) {
193	    std::fprintf(stderr, "andesim run --mode fast: %s\n", err.c_str());
194	    return 2;
195	  }
196	  // --gdb: inject QEMU's built-in GDB stub and pause at startup.
197	  if (cli.gdb) {
198	    const std::string port = cli.gdb_port.empty() ? "1234" : cli.gdb_port;
199	    extra.push_back("-gdb");
200	    extra.push_back("tcp::" + port);
201	    extra.push_back("-S");
202	  }
203	
204	  // --runtime linux: stage a manifested vlinux.elf that boots the app under
205	  // the proxy kernel. The ELF positional is the APP, not the boot image --
206	  // -bios loads the staged vlinux instead (run_standalone's boot_elf_override).
207	  Cli cli2 = cli;
208	  std::string boot_elf;
209	  if (cli.runtime == "linux") {
210	    if (int rc = check_one_elf(cli, "fast")) return rc;
211	    const std::string app_elf =
212	        abs_elf(cli.positional[0], "--mode fast --runtime linux");
213	    if (app_elf.empty()) return 2;
214	
215	    // mem_size_spec already passed qemu_m_args above (whole-MiB check, a
216	    // strictly tighter validation than parse_size alone), so this call
217	    // cannot fail: reused only to get the byte count for the manifest.
218	    const long long mem_bytes = parse_size(mem_size_spec, err);
219	
220	    std::string stage_err;
221	    boot_elf = stage_linux_runtime(app_elf, static_cast<uint64_t>(mem_bytes),
222	                                   cli.passthrough, stage_err);
223	    if (boot_elf.empty()) {
224	      std::fprintf(stderr, "andesim run --mode fast --runtime linux: %s\n",
225	                   stage_err.c_str());
226	      return 2;
227	    }
228	    log_line(kLogInfo, "[andesim] --runtime linux: staged %s (app=%s)",
229	             boot_elf.c_str(), app_elf.c_str());
230	
231	    // App argv (ROADMAP_LINUX_RUNTIME.md U8) travels through the manifest
232	    // above, not QEMU's own CLI -- clear it here so QEMU never sees it as
233	    // engine flags (e.g. "-m x.gguf" is not a memory size).
234	    cli2.passthrough.clear();
235	
236	    // Engine-synced CPU: the app + vlinux run on the hardware a hybrid
237	    // measurement targets, not the ax46 vplat default (last -cpu wins).
238	    extra.push_back("-cpu");
239	    extra.push_back("andes-ax45mpv,vlen=512");
240	  }
241	
242	  // Pick rv32 vs rv64. An explicit --engine (qemu32/qemu64) wins; otherwise read
243	  // the ELF's class so an rv32 program lands on qemu-system-riscv32 instead of
244	  // the rv64 default. Warn (do not fail) if an explicit choice contradicts the
245	  // ELF -- the override is the user's call.
246	  const int elf_w = cli.positional.empty() ? 0 : elf_xlen(cli.positional[0]);
247	  int xlen;
248	  if (cli.engine == kQemuId32) xlen = 32;
249	  else if (cli.engine == kQemuId64) xlen = 64;
250	  else xlen = elf_w ? elf_w : 64;  // no explicit engine: follow the ELF (else rv64)
251	  // Only an explicit engine can disagree with the ELF (when none is given, xlen
252	  // == elf_w), so this guard already implies an explicit --engine.
253	  if (elf_w && elf_w != xlen)
254	    std::fprintf(stderr,
255	                 "[andesim] --mode fast: --engine %s is rv%d but the ELF is rv%d "
256	                 "(running as rv%d)\n",
257	                 cli.engine.c_str(), xlen, elf_w, xlen);
258	  return run_standalone(cli2, builtin_qemu_arch(xlen), "fast", extra,
259	                        /*clean_output=*/false, boot_elf);
260	}
261	
262	// Block until 127.0.0.1:`port` is LISTENing (or `timeout_ms` elapses). vsim opens
263	// its --jtag-port only after it has reset and halted the hart, so the debugger we
264	// exec next must not race ahead of it -- OpenOCD/ICEman do not retry the bitbang
265	// connect, and a missed connect leaves the session dead. Non-intrusive: scans
266	// /proc/net/tcp rather than connecting (a probe connection would land in vsim's
267	// single debugger slot). Returns false on timeout.
268	static bool wait_for_jtag_port(uint16_t port, int timeout_ms = 20000) {
269	  constexpr int kPollMs = 50;
270	  for (int waited = 0; waited <= timeout_ms; waited += kPollMs) {
271	    if (std::FILE* f = std::fopen("/proc/net/tcp", "re")) {
272	      char line[512];
273	      while (std::fgets(line, sizeof line, f)) {
274	        // cols: sl  local_address(IP:port hex)  rem_address  st  ...
275	        // "%*8x:%x" skips the 8-hex-digit IPv4 and reads the local port; the
276	        // 0A (TCP_LISTEN) filter also drops the non-hex header row.
277	        unsigned lport = 0, st = 0;
278	        if (std::sscanf(line, "%*s %*8x:%x %*s %x", &lport, &st) == 2
279	            && st == 0x0A && lport == port) {
280	          std::fclose(f);
281	          return true;
282	        }
283	      }
284	      std::fclose(f);
285	    }
286	    std::this_thread::sleep_for(std::chrono::milliseconds(kPollMs));
287	  }
288	  return false;
289	}
290	
291	// `run --mode cycle --gdb`: start vsim with --jtag-port 9104 in the background
292	// (the hart free-runs; ICEman halts it over the JTAG DTM on connect), then exec
293	// ICEman ($ICEMAN env var) with `-Z v5 -I virtual_dmi.cfg` in the foreground.
294	int run_cycle_gdb(const Cli& cli, const EngineDescriptor& eng) {
295	  const char* iceman = std::getenv("ICEMAN");
296	  if (!iceman || !*iceman) {
297	    std::fprintf(stderr,
298	                 "andesim run --mode cycle --gdb: $ICEMAN not set "
299	                 "(export ICEMAN=<path to ICEman binary>)\n");
300	    return 2;
301	  }
302	  // Build vsim argv from the standalone template, appending user passthrough
303	  // and the JTAG port flag.
304	  const std::string elf = abs_elf(cli.positional[0], "--mode cycle --gdb");
305	  if (elf.empty()) return 2;
306	  const std::string jtag_port = cli.gdb_port.empty() ? "9104" : cli.gdb_port;
307	  std::vector<std::string> vsim_pass = cli.passthrough;
308	  vsim_pass.push_back("--jtag-port");
309	  vsim_pass.push_back(jtag_port);
310	  std::string err;
311	  const std::vector<std::string> vsim_argv =
312	      passthrough_argv(eng, "standalone", elf, vsim_pass, err);
313	  if (!err.empty()) {
314	    std::fprintf(stderr, "andesim run --mode cycle --gdb: %s\n", err.c_str());
315	    return 2;
316	  }
317	  std::fprintf(stderr,
318	               "[andesim] --gdb: vsim JTAG on port %s, exec ICEman\n",
319	               jtag_port.c_str());
320	  if (fork_background(vsim_argv) < 0) {
321	    std::fprintf(stderr,
322	                 "andesim run --mode cycle --gdb: failed to fork vsim\n");
323	    return 1;
324	  }
325	  // vsim opens the JTAG port and the hart free-runs; ICEman halts it on connect.
326	  // Wait for the port to be LISTENing before launching the debugger (it does not
327	  // retry the bitbang connect). Numeric ports only; a non-numeric --gdb-port
328	  // (atoi -> 0) skips the wait and lets the engine reject it. Best-effort: warn
329	  // but launch anyway if it never appears.
330	  if (const int pnum = std::atoi(jtag_port.c_str());
331	      pnum > 0 && !wait_for_jtag_port(static_cast<uint16_t>(pnum)))
332	    std::fprintf(stderr,
333	                 "[andesim] --gdb: warning: vsim JTAG port %s not LISTENing "
334	                 "after 20s; launching the debugger anyway\n",
335	                 jtag_port.c_str());
336	  // -I virtual_dmi.cfg selects ICEman's remote_bitbang interface (host
337	  // localhost, port 9104) instead of its default real-hardware adapter; without
338	  // it ICEman finds no adapter and exits. The cfg is found relative to the cwd
339	  // (repo root) in interface/; it pins port 9104, matching --jtag-port's default.
340	  return exec_passthrough({iceman, "-Z", "v5", "-I", "virtual_dmi.cfg"});
341	}
