392	// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
393	// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle
394	// figure is the vsim mcycle minus QEMU1's drained mcycle. Replaces the Python
395	// driver's tests/e2e.sh delegation with a single window-cycle line.
396	int run_hybrid(const Cli& cli) {
397	  // Single diagnostic sink for the early-validation returns: prefix + exit 2.
398	  auto fail = [](const std::string& msg) {
399	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
400	    return 2;
401	  };
402	
403	  // --print-memmap: the map describes the run's window (engine + --mem-size),
404	  // not a workload, so the ELF is optional (when given it only adds the
405	  // fit-vs-scratch note) and the trigger machinery is skipped entirely.
406	  const bool memmap_only = cli.print_memmap;
407	  if (!memmap_only) {
408	    if (int rc = check_one_elf(cli, "hybrid")) return rc;
409	  } else if (cli.positional.size() > 1) {
410	    return fail("unexpected argument '" + cli.positional[1] + "'");
411	  }
412	
413	  // Resolve to an absolute, existing ELF through the shared resolver -- the same
414	  // check and "ELF not found" message fast/cycle get (abs_elf already printed on
415	  // failure). pc-trigger resolution below then reads the ELF's .symtab.
416	  std::string elf_path;
417	  if (!cli.positional.empty()) {
418	    elf_path = abs_elf(cli.positional[0], "--mode hybrid");
419	    if (elf_path.empty()) return 2;
420	  }
421	  const fs::path elf{elf_path};  // for .stem() in the banner / PASS lines
422	
423	  // Validate everything cheap BEFORE the expensive engine discovery, so a CLI
424	  // mistake fails fast without spawning a --describe per Verilator build.
425	  std::string err;
426	  Trigger trig;
427	  std::vector<std::string> vsim_extras;
428	  if (!memmap_only) {
429	    trig = hybrid_trigger(cli, elf_path, err);
430	    if (!err.empty()) return fail(err);
431	
432	    // hybrid_trigger has already guaranteed trig.kind is marker|pc (the only
433	    // hybrid triggers; unknown returned an error above) -- exactly the entry
434	    // boundary --verify needs the oracle to arm on.
435	    vsim_extras = vsim_extra_args(cli, trig.kind, err);
436	    if (!err.empty()) return fail(err);
437	  }
438	
439	  // --runtime linux (U9) defaults --mem-size to 1G, same as fast (U2) --
440	  // the app + vlinux's own arenas need more than the plain hybrid default.
441	  long long mem = cli.runtime == "linux" ? 1024LL * 1024 * 1024
442	                                         : 128LL * 1024 * 1024;
443	  if (!cli.mem_size.empty()) {
444	    std::string se;
445	    mem = parse_size(cli.mem_size, se);
446	    if (!se.empty()) return fail("--mem-size: " + se);
447	    // Early cap: QEMU's AE350 DRAM window is 2 GiB and the backend doubles as
448	    // guest RAM here. The physical mmap reserves one V-scratch page above the
449	    // program's RAM (L26/F2), so the usable --mem-size is 2 GiB minus that
450	    // page. Failing now beats allocating a huge mmap file first and letting
451	    // QEMU die late.
452	    if (mem > max_program_mem_bytes())
453	      return fail("--mem-size " + cli.mem_size +
454	                  " exceeds the AE350 DRAM window (2G minus the V-scratch "
455	                  "reservation)");
456	  }
457	
458	  // L26/F3: refuse a run whose static image would extend into the reserved
459	  // V-transport scratch page. Scheme D parks the scratch in the TOP page of the
460	  // physical mmap; a PT_LOAD segment reaching there means the ELF was linked for
461	  // more RAM than --mem-size grants, and QEMU would load it straight onto the
462	  // scratch -> silent corruption. Derive the page's start from
463	  // physical_mmap_bytes (the same sizing the mmap uses) rather than a bare
464	  // `mem`, so the threshold tracks the reservation shape instead of relying on
465	  // the +page/-page adjustments cancelling. ram_base is the fixed andes_ae350
466	  // DRAM base (0; see L10). Skipped when the ELF cannot be read -- downstream
467	  // reports it.
468	  {
469	    std::string e;
470	    const uint64_t top = elf_load_top(elf_path, e);
471	    const uint64_t scratch_gpa =
472	        static_cast<uint64_t>(physical_mmap_bytes(mem)) - HYBRID_V_SCRATCH_BYTES;
473	    if (e.empty() && top > scratch_gpa) {
474	      char msg[256];
475	      std::snprintf(msg, sizeof(msg),
476	                    "ELF static image ends at 0x%llx, overlapping the reserved "
477	                    "V-transport scratch page at 0x%llx (ram_base + --mem-size)"
478	                    "; raise --mem-size or shrink the image",
479	                    static_cast<unsigned long long>(top),
480	                    static_cast<unsigned long long>(scratch_gpa));
481	      return fail(msg);
482	    }
483	  }
484	
485	  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
486	  // or the sole cycle-accurate engine (reusing the F8 selector).
487	  Discovery disc = discover_engines();
488	  const EngineDescriptor* acc =
489	      resolve_accurate_engine(disc.engines, cli.engine, err);
490	  if (!acc) {
491	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
492	    for (const std::string& w : disc.warnings)
493	      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
494	    return 2;
495	  }
496	
497	  // ISA sync: both legs must agree on the base ISA width (rv32 engines
498	  // cannot share architectural state with the rv64 fast leg).
499	  if (std::string hw = hybrid_hw_check(*acc); !hw.empty()) return fail(hw);
500	  // ...and the ELF must match that engine width too (same guard as cycle).
501	  if (std::string e = elf_engine_arch_error(elf_path, *acc); !e.empty())
502	    return fail(e);
503	
504	  if (memmap_only) {
505	    // The LM/HVM bases come from the same probe run_plan stages as the fast
506	    // leg's -readconfig, so the printed geometry IS the run's effective one.
507	    // Tolerant like stage_qemu_cfg: a probe failure only drops the LM rows
508	    // (hybrid_memmap warns).
509	    const RunResult probe =
510	        run_process({acc->bin_path, "--print-qemu-config"}, 5000);
511	    const std::string cfg =
512	        (!probe.spawn_failed && !probe.timed_out && probe.rc == 0) ? probe.out
513	                                                                   : "";
514	    std::fprintf(stderr, "[andesim] hybrid memory map: engine=%s mem-size=%s\n",
515	                 acc->id.c_str(),
516	                 fmt_size(static_cast<uint64_t>(mem)).c_str());
517	    std::fputs(render_memmap(hybrid_memmap(*acc, mem, cfg)).c_str(), stdout);
518	    // With an ELF given, say where its static image lands in that window.
519	    if (!elf_path.empty()) {
520	      std::string e;
521	      const uint64_t top = elf_load_top(elf_path, e);
522	      if (e.empty())
523	        std::printf("ELF %s: static image top 0x%llx (%s)\n",
524	                    elf.stem().string().c_str(),
525	                    static_cast<unsigned long long>(top),
526	                    top <= static_cast<uint64_t>(mem)
527	                        ? "fits DRAM"
528	                        : "OVERLAPS the reserved V-scratch page; raise "
529	                          "--mem-size");
530	    }
531	    return 0;
532	  }
533	
534	  // --runtime linux (U9): stage a manifested vlinux.elf that boots the app
535	  // under the proxy kernel, same as run_fast -- but here BOTH legs share
536	  // plan.elf (Plan's own contract: "the ELF every leg launches"), so
537	  // staging once and pointing plan.elf at the result covers the fast-
538	  // forward QEMU leg AND the vsim accurate leg with no per-leg special
539	  // casing. PC-mode triggers already resolved --pc-start/--pc-end against
540	  // elf_path (the app's own ELF, correctly) BEFORE this point -- vlinux's
541	  // own symbol table would have been the wrong one for that lookup.
542	  std::string boot_elf = elf_path;
543	  if (cli.runtime == "linux") {
544	    std::string stage_err;
545	    boot_elf = stage_linux_runtime(elf_path, static_cast<uint64_t>(mem),
546	                                   cli.passthrough, stage_err);
547	    if (boot_elf.empty()) return fail(stage_err);
548	    log_line(kLogInfo, "[andesim] --runtime linux: staged %s (app=%s)",
549	             boot_elf.c_str(), elf_path.c_str());
550	  }
551	
552	  Plan plan;
553	  plan.elf = boot_elf;
554	  plan.mem_size = mem;
555	  Step qemu_step{kQemuId64, "fast-leg", trig};
556	  Step vsim_step{acc->id, "accurate-leg", trig};
557	  // --runtime linux + marker mode: vsim's OWN trigger only static-pre-scans
558	  // whatever ELF it is handed (hybrid::CsrTrigger::scan_buffer, vsim_andesim
559	  // src/hybrid/csr_trigger.hpp) -- but under --runtime linux vsim boots
560	  // vlinux-run.elf, and the marker HINTs are in the APP's ELF, which vlinux
561	  // only loads into memory at RUNTIME (never part of vlinux-run.elf's own
562	  // static PT_LOAD content). QEMU1's plugin has no such limitation (a TCG
563	  // plugin watches the EXECUTED instruction stream, content-agnostic), which
564	  // is why only vsim's leg needs a workaround here. Fix: resolve the exit
565	  // marker's PC by scanning elf_path (the app's real ELF) on the driver
566	  // side, using the SAME shared predicate vsim's own scanner uses
567	  // (hybrid/insn_match.h -- bit-for-bit the same match, not a reimplementation
568	  // that could drift), and feed it to vsim through the EXISTING PC-mode
569	  // trigger machinery (`--hybrid-exit-pc`, already wired for --trigger pc)
570	  // instead of marker mode. QEMU1 keeps ordinary marker-mode unchanged (its
571	  // detection already works); only vsim's own trigger config changes. This
572	  // needs ZERO changes to vsim's own source, matching the roadmap's explicit
573	  // "hybrid transport, triggers, plugin, resume driver, and engines need NO
574	  // changes" constraint.
575	  if (cli.runtime == "linux" && trig.kind == "marker") {
576	    const RoiMarkerPcs m = find_roi_markers(elf_path);
577	    if (m.exit_pc == 0)
578	      return fail("no ROI exit marker (slti x0,x0,0x5A1) found in " + elf_path +
579	                  " -- add <andesim/ROI.h>'s andesim_ROI_begin()/end() around "
580	                  "the region to measure");
581	    char pcbuf[32];
582	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
583	                  static_cast<unsigned long long>(m.exit_pc));
584	    vsim_step.trigger = Trigger{"pc", {{"exit_pc", pcbuf}}};
585	  }
586	  vsim_step.extra_args = std::move(vsim_extras);  // kanata, validated
587	  // #1: with no --verify the driver consumes only the vsim mcycle delta, so ask
588	  // the accurate leg to drain just the counters and skip the full register-file
589	  // readback (~190 DM abstract commands). --verify keeps the full drain so the
590	  // oracle diff sees every field. Driver policy lives here next to the rest of
591	  // the verify reasoning, not in vsim_extra_args (user-forwarded flags only).
592	  if (!cli.verify)
593	    vsim_step.extra_args.push_back("--drain-minimal");
594	  // L4: the vsim leg speaks the same --log-level scale; forward ours so one
595	  // flag tunes the whole pipeline (its stderr is relayed at <= debug).
596	  vsim_step.extra_args.push_back("--log-level");
597	  vsim_step.extra_args.push_back(std::to_string(log_threshold()));
598	  plan.steps = {qemu_step, vsim_step};
599	
600	  // Banner to stderr so the window-cycle result stands alone on stdout.
601	  // vlen is the synced value the fast leg inherits from the engine.
602	  log_line(kLogDebug,
603	           "[andesim] model=hybrid engine=%s vlen=%ld trigger=%s fixture=%s",
604	           acc->id.c_str(), synced_vlen(acc->vlen), trig.kind.c_str(),
605	           elf.stem().string().c_str());
606	  // L3 decision log: why THIS engine.
607	  log_line(kLogDebug, "[andesim] engine: %s (%s)", acc->id.c_str(),
608	           cli.engine.empty() ? "sole cycle-accurate engine"
609	                              : "selected by --engine");
610	
611	  PlanOptions opts;
612	  opts.dry_run = cli.dry_run;
613	  if (!parse_positive_int(cli.step_timeout_ms, opts.timeout_ms, opts.timeout_ms))
614	    return fail("--step-timeout-ms: not a positive integer: " +
615	                cli.step_timeout_ms);
616	  const PlanResult r = run_plan(plan, disc.engines, opts);
617	  if (!r.ok()) {
618	    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
619	    if (!r.repro_dir.empty())
620	      std::fprintf(stderr,
621	                   "[andesim] repro: kept run artifacts at %s "
622	                   "(see manifest.txt)\n",
623	                   r.repro_dir.c_str());
624	    if (!log_file_path().empty())
625	      std::fprintf(stderr, "[andesim] repro: full log at %s\n",
626	                   log_file_path().c_str());
627	    return 1;
628	  }
629	  // --dry-run: print the exact per-leg commands run_plan assembled -- the QEMU
630	  // fast leg (incl. the staged -readconfig from the engine's --print-qemu-config)
631	  // then the vsim accurate leg -- and stop. Nothing was spawned.
632	  if (cli.dry_run) {
633	    std::vector<std::string> labels;
634	    labels.reserve(plan.steps.size());
635	    for (const Step& s : plan.steps)
636	      labels.push_back(s.role + " [" + s.engine_id + "]");
637	    return print_dry_run(r.argvs, labels);
638	  }
639	  // Relay each leg's stdout: the program's own prints (QEMU1 phase-1 output,
640	  // then anything the ROI wrote on vsim) belong to the user. The vsim
641	  // (accurate) leg's output is prefixed by vsim's startup banner (Copyright /
642	  // Version) -- strip it so only real program output shows, the same as `cycle`
643	  // does; its [info] log is already absent (the leg's stderr was dropped at
644	  // capture). The QEMU leg has no banner, so it relays verbatim.
645	  for (size_t i = 0; i < r.phases.size(); ++i) {
646	    const std::string& out = r.phases[i].out;
647	    if (out.empty()) continue;
648	    if (i < plan.steps.size() && plan.steps[i].role == "accurate-leg") {
649	      const std::string shown = strip_vsim_banner(out);
650	      std::fwrite(shown.data(), 1, shown.size(), stdout);
651	    } else {
652	      std::fwrite(out.data(), 1, out.size(), stdout);
653	    }
654	  }
655	  // phases[0] = QEMU1 drain, [1] = vsim drain; the kernel/window figure is the
656	  // vsim mcycle delta.
657	  {
658	    const unsigned long long q_mc = r.phases[0].mcycle;
659	    const unsigned long long v_mc = r.phases[1].mcycle;
660	    // The answer line, same shape as cycle mode; the raw mcycle operands are
661	    // debug detail.
662	    log_result(kLogInfo, "[andesim] %llu cycles", v_mc - q_mc);
663	    log_result(kLogDebug,
664	               "[andesim] window: trigger=%s vsim mcycle=%llu qemu mcycle=%llu",
665	               trig.kind.c_str(), v_mc, q_mc);
666	  }
667	
668	  // v6 incompatibility surface: the QEMU1 drain's write-mask records which
669	  // config CSRs the program actually wrote; any of them this engine does not
670	  // implement would TRAP on its silicon (the program would never reach the
671	  // ROI), yet the hybrid restore silently skipped it. Warn -- the figure may
672	  // not represent this engine running this program.
673	  {
674	    const std::string w = unsupported_written_warning(
675	        r.phases[0].st, acc->andes_csrs, acc->id);
676	    if (!w.empty() && log_on(kLogWarn)) std::fputs(w.c_str(), stderr);
677	  }
678	
679	  // --verify (verify_oracle F4, default off): re-run the ELF on pure QEMU
680	  // with the plugin draining at the ROI exit boundary, sampling at vsim's
681	  // halt pc, and diff the two drains in-process. The oracle plan gets its
682	  // own fresh mmap: reusing the main run's would boot the oracle on the
683	  // hybrid run's leftover memory. Its stdout is dropped -- the program's
684	  // output was already relayed from the main run.
685	  if (cli.verify) {
686	    char pcbuf[32];
687	    std::snprintf(pcbuf, sizeof(pcbuf), "0x%llx",
688	                  static_cast<unsigned long long>(r.phases[1].st.pc));
689	    Trigger vtrig;
690	    vtrig.kind = "verify-" + trig.kind;
691	    if (trig.kind == "pc") vtrig.params["exit_pc"] = trig.params.at("exit_pc");
692	    vtrig.params["drain_pc"] = pcbuf;
693	
694	    Plan vplan;
695	    vplan.elf = elf_path;
696	    vplan.mem_size = mem;
697	    vplan.steps = {Step{kQemuId64, "fast-leg", vtrig}};
698	    // The oracle must model the same hardware as the main run's accurate
699	    // engine ({vlen}/{qemu_cpu}/-readconfig sync) -- without this it ran the
700	    // family-default CPU and false-diffed on vlenb (and, on an H-capable
701	    // engine, on mideleg's read-only-one delegation bits).
702	    vplan.hw_engine_id = acc->id;
703	
704	    log_line(kLogDebug,
705	             "[andesim] verify: oracle leg (pure QEMU drains at the ROI "
706	             "exit, pc=%s)",
707	             pcbuf);
708	    const PlanResult vr = run_plan(vplan, disc.engines);
709	    if (!vr.ok()) {
710	      std::fprintf(stderr, "andesim run --verify: %s\n", vr.error.c_str());
711	      if (!vr.repro_dir.empty())
712	        std::fprintf(stderr,
713	                     "[andesim] repro: kept run artifacts at %s "
714	                     "(see manifest.txt)\n",
715	                     vr.repro_dir.c_str());
716	      return 1;
717	    }
718	    // Pass the cycle engine's supported Andes-CSR list so verify skips CSRs the
719	    // engine does not implement (it never restored/re-read them; comparing
720	    // would false-diff). Mirrors the resume/drain gating in vsim.
721	    const DiffReport d =
722	        diff_states(vr.phases[0].st, r.phases[1].st, acc->andes_csrs);
723	    print_diff_report(d);
724	    if (!d.ok()) {
725	      std::fprintf(stderr,
726	                   "andesim run --verify: vsim drain diverges from the "
727	                   "QEMU oracle\n");
728	      return 1;
729	    }
730	    log_result(kLogInfo, "[verify] PASS: vsim drain matches the QEMU oracle");
731	  }
732	
733	  log_result(kLogDebug, "PASS: --mode hybrid --trigger %s (%s)",
734	             trig.kind.c_str(), elf.stem().string().c_str());
735	  return 0;
736	}
