11	// A "" -> `def` positive-int CLI knob (e.g. --limit, --min-iters,
12	// --step-timeout-ms): empty string keeps the default; otherwise the whole
13	// string must parse as a positive integer or this returns false.
14	inline bool parse_positive_int(const std::string& v, int def, int& out) {
15	  if (v.empty()) {
16	    out = def;
17	    return true;
18	  }
19	  try {
20	    size_t pos = 0;
21	    out = std::stoi(v, &pos);
22	    return pos == v.size() && out > 0;
23	  } catch (...) {
24	    return false;
25	  }
26	}
