45	// L2: on a leg failure, keep the run's evidence so the bug can be reported
46	// and reproduced: the workdir files (drained states, LM sidecars, staged
47	// qemu cfg), a copy of the ELF, and manifest.txt with the error and every
48	// leg's exact command. The big shared mmap is NOT kept (the legs are
49	// deterministic; re-running the kept commands regenerates it). Returns the
50	// bundle dir, or "" when it cannot be written (never fails the caller).
51	std::string save_repro_bundle(const std::string& wd, const Plan& plan,
52	                              const std::vector<std::vector<std::string>>& argvs,
53	                              size_t failed_step, const std::string& error) {
54	  const std::string cache = andesim_cache_dir();
55	  if (cache.empty()) return "";
56	  std::error_code ec;
57	  const fs::path root = fs::path(cache) / "repro";
58	  fs::create_directories(root, ec);
59	  if (ec) return "";
60	
61	  char ts[32];
62	  const std::time_t now = std::time(nullptr);
63	  std::tm tm{};
64	  gmtime_r(&now, &tm);
65	  std::strftime(ts, sizeof(ts), "%Y%m%dT%H%M%SZ", &tm);
66	  const std::string stem = fs::path(plan.elf).stem().string();
67	  fs::path dir = root / (std::string(ts) + "-" + stem);
68	  for (int n = 1; fs::exists(dir, ec); ++n)  // same-second collisions
69	    dir = root / (std::string(ts) + "-" + stem + "." + std::to_string(n));
70	  fs::create_directories(dir, ec);
71	  if (ec) return "";
72	
73	  fs::copy(wd, dir, fs::copy_options::recursive, ec);  // whatever the legs left
74	  fs::copy_file(plan.elf, dir / fs::path(plan.elf).filename(),
75	                fs::copy_options::skip_existing, ec);
76	
77	  std::ofstream m(dir / "manifest.txt");
78	  m << "error: " << error << "\n";
79	  m << "elf: " << plan.elf << "\n";
80	  m << "failed step: " << failed_step << " (" << plan.steps[failed_step].role
81	    << " [" << plan.steps[failed_step].engine_id << "])\n";
82	  for (size_t i = 0; i < argvs.size(); ++i)
83	    m << "step " << i << " " << plan.steps[i].role << " ["
84	      << plan.steps[i].engine_id << "]: " << render_argv(argvs[i]) << "\n";
85	  m << "note: the shared mmap is not kept; the commands above regenerate the "
86	       "run deterministically\n";
87	  m.close();
88	
89	  prune_repro_bundles(root, kMaxReproBundles);
90	  return dir.string();
91	}
