154	std::string plan_step_rc_error(size_t step, const Step& s, int expect_rc,
155	                               int got_rc) {
156	  std::string m = "plan step " + std::to_string(step) + ": expected exit " +
157	                  std::to_string(expect_rc) + ", got " + std::to_string(got_rc);
158	  // A drain step (expect_rc is the handoff/drain code) that exits 0 ran the ELF
159	  // to completion without ever hitting its ROI boundary -- the marker/pc
160	  // trigger never fired. This is THE common "unmarked ELF / wrong trigger"
161	  // mistake; name the kind so the fix is obvious, not a bare exit code.
162	  if (got_rc == 0 && expect_rc == kDrainRc)
163	    m += " -- the " + s.role + " ran to completion without reaching its " +
164	         s.trigger.kind +
165	         " trigger boundary (the ROI never drained; check the ELF actually "
166	         "reaches the " +
167	         s.trigger.kind + ")";
168	  return m;
169	}
