28	// `run --mode fast` resolves qemu directly, skipping the per-engine --describe
29	// scan whole-registry discovery would spawn.
30	EngineDescriptor builtin_qemu_arch(int xlen) {
31	  const bool rv32 = (xlen == 32);
32	  EngineDescriptor d;
33	  d.id = rv32 ? kQemuId32 : kQemuId64;
34	  d.type = "qemu";
35	  d.kind = "functional";
36	  d.xlen = xlen;
37	  d.triggers = {"marker", "pc"};
38	  d.state = {"drain"};
39	  d.source = "built-in";
40	
41	  d.roles = {"standalone"};
42	  if (!rv32) {  // hybrid rv32 (qemu32 fast-leg + engine-matched -cpu) not wired yet
43	    // The hybrid fast-forward leg (rv64): load the ELF, drain on the plugin's
44	    // trigger into {state_out}, exit 200. {plugin}/{mmap}/{mmap_size}/{state_out}
45	    // are filled by the plan executor (F6); {trigger} is the plugin comma-suffix
46	    // (empty for marker), folded by leg_trigger_args (F9).
47	    d.roles.push_back("fast-leg");
48	    // {qemu_cpu}: the accurate engine's CPU model (from its --print-qemu-config
49	    // driver globals; run_plan falls back to the andes-ax45mpv family default).
50	    // The -readconfig globals apply only to the driver they name, so the model
51	    // must follow the engine -- andes-ax45mpv silently kept vlen=512 when the
52	    // ax66 (VLEN 128) pairing asked for 128.
53	    d.invoke.push_back(
54	        {"fast-leg",
55	         {"{bin}", "-object",
56	          "memory-backend-file,id=mem,share=on,mem-path={mmap},size={mmap_size}",
57	          "-machine", "andes_ae350,memory-backend=mem", "-cpu",
58	          "{qemu_cpu},vlen={vlen}", "-nographic", "-semihosting-config",
59	          "enable=on,target=native", "-bios", "{elf}", "-plugin",
