139	Cli parse_cli(int argc, char** argv) {
140	  std::vector<std::string> args;
141	  args.reserve(argc > 1 ? static_cast<size_t>(argc - 1) : 0);
142	  for (int i = 1; i < argc; ++i) args.emplace_back(argv[i]);
143	  return parse_cli(args);
144	}
