79	static void test_filter_loops() {
80	  auto d = parse_disasm(kDisasm);
81	  std::vector<LoopEdge> rows = {
82	      {0x80001008, 0x8000100c, 50},   // scalar-only body
83	      {0x80001000, 0x80001014, 640},  // has RVV
84	      {0x80002000, 0x80002008, 3},    // below min_iters
85	      {0x80001010, 0x80001010, 3200}, // has RVV (vadd.vv)
