90	  CHECK(out[0].iters == 3200 && out[1].iters == 640);  // sorted desc
91	
92	  // rvv_only=false keeps the scalar loop; limit truncates after sorting.
93	  auto all = filter_loops(rows, 10, false, d, 2);
