98	static void test_build_loops_nesting() {
99	  std::vector<LoopEdge> rows = {
100	      {0x100, 0x200, 900},  // L1: outer
101	      {0x120, 0x180, 800},  // L2: inside L1
102	      {0x130, 0x160, 700},  // L3: inside L2 (smallest enclosing wins)
103	      {0x300, 0x310, 600},  // L4: disjoint
104	      {0x300, 0x310, 500},  // L5: identical range to L4 -> NOT its parent
105	  };
106	  auto loops = build_loops(rows, 50);
107	  CHECK(loops.size() == 5);
108	  CHECK(loops[0].id == "L1" && loops[0].parent == -1);
109	  CHECK(loops[1].parent == 0);   // L2 in L1
110	  CHECK(loops[2].parent == 1);   // L3 in L2, not L1
111	  CHECK(loops[3].parent == -1);
112	  CHECK(loops[4].parent == -1);  // identical range excluded
113	  CHECK(loops[0].children.size() == 1 && loops[0].children[0] == 1);
114	  CHECK(loops[1].children.size() == 1 && loops[1].children[0] == 2);
115	  CHECK(loops[3].children.empty());
116	
117	  // limit caps how many rows become loops.
118	  CHECK(build_loops(rows, 2).size() == 2);
119	}
