42	// fork + (optional stdin from /dev/null) + exec.
43	// When `wait` is true (the default) waits for the child and returns its exit
44	// code, 128+signal if signalled, or -1 on failure. When `wait` is false
45	// returns the child pid immediately without waiting (caller owns the child).
46	// Backs exec_passthrough (run fast/cycle: stdin inherited) and
47	// fork_background (no wait).
48	int spawn_inherit(const std::vector<std::string>& argv,
49	                  bool stdin_from_devnull, bool wait = true) {
50	  if (argv.empty()) return -1;
51	
52	  pid_t pid = fork();
53	  if (pid < 0) return -1;
54	
55	  if (pid == 0) {  // child
56	    if (stdin_from_devnull) {
57	      int devnull = open("/dev/null", O_RDONLY);
58	      if (devnull >= 0) {
59	        dup2(devnull, STDIN_FILENO);
60	        if (devnull > 2) close(devnull);
61	      }
62	    }
63	    exec_or_die(argv);
64	  }
65	
66	  if (!wait) return static_cast<int>(pid);
67	  return wait_for_exit_code(pid);
68	}
